package com.dndmaster.combatmap.application.view;
import com.dndmaster.combatmap.domain.*; import java.util.*;
public record PlayerCombatMapView(MapId mapId,GridSpec grid,List<CombatToken> tokens,Set<GridPosition> obstacles,List<MapLayer> layers,Set<GridPosition> current,Set<GridPosition> explored,long version){public PlayerCombatMapView{tokens=List.copyOf(tokens);obstacles=Set.copyOf(obstacles);layers=List.copyOf(layers);current=Set.copyOf(current);explored=Set.copyOf(explored);if(layers.stream().anyMatch(l->l.visibility()!=LayerVisibility.PLAYER_VISIBLE))throw new IllegalArgumentException("player view contains AI_ONLY layer");if(!explored.containsAll(current)||version<0)throw new IllegalArgumentException("invalid player visibility");}}
